#!/usr/bin/env Rscript
a<-commandArgs(FALSE);f<-grep("^--file=",a,value=TRUE);sd<-dirname(normalizePath(sub("^--file=","",f[1])));repo<-normalizePath(file.path(sd,"..",".."),mustWork=TRUE);d<-read.csv(file.path(repo,"data_public","figure_source_data","Supplementary_Figures","FigS6_mouse_level_formal_inputs.csv"),check.names=FALSE);o<-do.call(rbind,lapply(unique(paste(d$panel,d$endpoint,sep="||")),function(k){z<-d[paste(d$panel,d$endpoint,sep="||")==k,];tt<-t.test(z$value[z$group=="DSS"],z$value[z$group=="Control"],var.equal=TRUE);data.frame(panel=z$panel[1],endpoint=z$endpoint[1],t=unname(tt$statistic),df=unname(tt$parameter),P=tt$p.value)}));o$BH_FDR<-ave(o$P,o$panel,FUN=function(x)p.adjust(x,"BH"));ref<-read.csv(file.path(repo,"data_public","figure_source_data","Animal_numerical_data","animal_endpoint_multiplicity_BH.csv"),check.names=FALSE);ref<-ref[ref$Figure=="Supplementary Figure S5",c("Panel","Endpoint","Raw_P","BH_adjusted_P")];m<-merge(o,ref,by.x=c("panel","endpoint"),by.y=c("Panel","Endpoint"));m$exact_PASS<-abs(m$P-m$Raw_P)<1e-12&abs(m$BH_FDR-m$BH_adjusted_P)<1e-12;dir.create(file.path(repo,"results_reproduced","imaging"),recursive=TRUE,showWarnings=FALSE);write.csv(m,file.path(repo,"results_reproduced","imaging","FigS6_statistics_reproduced.csv"),row.names=FALSE);stopifnot(nrow(m)==7,all(m$exact_PASS))
